  body.innerHTML = APOCRIFOS_INFO.map(x=>'<div style="margin-bottom:14px;"><div style="font-weight:700;color:var(--rubric);margin-bottom:4px;">'+x.t+'</div><div style="color:var(--ink);">'+x.d+'</div></div>').join('');
