function seferTourFindEl(sel){
  if(!sel) return null;
  for(const part of sel.split(',')){
    const el = document.querySelector(part.trim());
    if(el && (el.offsetParent !== null || el.getClientRects().length > 0)) return el;
  }
  return document.querySelector(sel.split(',')[0].trim());
}
function seferTourPlaceCard(target){
  const card = document.getElementById('sefer-tour-card');
  const spot = document.getElementById('sefer-tour-spot');
  if(!card) return;
  const margin = 12;
  const cw = card.offsetWidth || 320;
  const ch = card.offsetHeight || 160;
  let top, left;
  if(target){
    const r = target.getBoundingClientRect();
    spot.style.display = 'block';
    spot.style.top = Math.max(8, r.top - 6) + 'px';
    spot.style.left = Math.max(8, r.left - 6) + 'px';
    spot.style.width = Math.min(window.innerWidth - 16, r.width + 12) + 'px';
    spot.style.height = Math.min(window.innerHeight - 16, r.height + 12) + 'px';
    top = r.bottom + 14;
    left = Math.min(Math.max(margin, r.left), window.innerWidth - cw - margin);
    if(top + ch > window.innerHeight - margin){
      top = Math.max(margin, r.top - ch - 14);
    }
  } else {
    spot.style.display = 'none';
    top = window.innerHeight / 2 - ch / 2;
    left = window.innerWidth / 2 - cw / 2;
  }
  card.style.top = Math.max(margin, Math.min(top, window.innerHeight - ch - margin)) + 'px';
  card.style.left = Math.max(margin, Math.min(left, window.innerWidth - cw - margin)) + 'px';
}
function seferTourShowStep(){
  const step = SEFER_TOUR_STEPS[seferTourIndex];
  if(!step){ endSeferTour(); return; }
  const title = document.getElementById('sefer-tour-title');
  const text = document.getElementById('sefer-tour-text');
  const num = document.getElementById('sefer-tour-step');
  const next = document.getElementById('sefer-tour-next');
  const prev = document.getElementById('sefer-tour-prev');
  if(title) title.textContent = step.title;
  if(text) text.textContent = step.text;
  if(num) num.textContent = (seferTourIndex + 1) + '/' + SEFER_TOUR_STEPS.length;
  if(next) next.textContent = seferTourIndex >= SEFER_TOUR_STEPS.length - 1 ? 'Finalizar' : 'Siguiente';
  if(prev) prev.disabled = seferTourIndex <= 0;
  const el = seferTourFindEl(step.sel);
  if(el && el.scrollIntoView){
    try{ el.scrollIntoView({block:'nearest', behavior:'smooth'}); }catch(e){}
  }
  requestAnimationFrame(()=> seferTourPlaceCard(el));
}
function startSeferTour(){
  document.getElementById('info-modal')?.classList.remove('open');
  seferTourActive = true;
  seferTourIndex = 0;
  updateProjectBtnVisibility();
  document.getElementById('sefer-tour-overlay')?.classList.add('open');
  document.getElementById('sefer-tour-card').style.display = 'block';
  seferTourShowStep();
}
function endSeferTour(){
  seferTourActive = false;
  updateProjectBtnVisibility();
  document.getElementById('sefer-tour-overlay')?.classList.remove('open');
  const spot = document.getElementById('sefer-tour-spot');
  const card = document.getElementById('sefer-tour-card');
  if(spot) spot.style.display = 'none';
  if(card) card.style.display = 'none';
}
document.getElementById('sefer-tour-next')?.addEventListener('click', ()=>{
  if(seferTourIndex >= SEFER_TOUR_STEPS.length - 1) endSeferTour();
  else { seferTourIndex++; seferTourShowStep(); }
});
document.getElementById('sefer-tour-prev')?.addEventListener('click', ()=>{
  if(seferTourIndex > 0){ seferTourIndex--; seferTourShowStep(); }
});
document.getElementById('sefer-tour-skip')?.addEventListener('click', endSeferTour);
window.addEventListener('resize', ()=>{ if(seferTourActive) seferTourShowStep(); });
document.addEventListener('keydown', (e)=>{
  if(!seferTourActive) return;
  if(e.key === 'Escape'){ e.preventDefault(); endSeferTour(); }
  if(e.key === 'ArrowRight' || e.key === 'Enter'){ e.preventDefault(); document.getElementById('sefer-tour-next')?.click(); }
  if(e.key === 'ArrowLeft'){ e.preventDefault(); document.getElementById('sefer-tour-prev')?.click(); }
}, true);
function openSeferHelp(){
  infoNavEnabled = false;
  document.getElementById('im-nav').style.display = 'none';
  document.getElementById('im-title').textContent = 'Instrucciones de SEFER';
  document.getElementById('im-sub').textContent = 'BY LIFE WORD MISSION·Reina-Valera 1960';
  document.getElementById('im-body').innerHTML = `
    <button type="button" class="btn primary tour-start-btn" id="start-sefer-tour-btn">🎯 Iniciar tour interactivo</button>
    <div class="im-block"><div class="im-label">¿Qué es SEFER?</div>
    <div class="im-text">Biblia de estudio y proyección (Reina-Valera 1960) de <strong>Life Word Mission Playa del Carmen</strong>. Sirve para leer, tomar notas, marcar favoritos, proyectar versículos y estudiar con calma.</div></div>
    <div class="im-block"><div class="im-label">Tour guiado</div>
    <div class="im-text">Pulsa <strong>Iniciar tour</strong> para un recorrido paso a paso por la pantalla. Puedes salir con <strong>Esc</strong>. Ideal si es tu primera vez.</div></div>
    <div class="im-block"><div class="im-label">Libros y capítulos</div>
    <div class="im-text">• A la izquierda: Antiguo y Nuevo Testamento. Abre un libro y elige un capítulo.<br>
    • Botón <strong>📚</strong> junto al nombre: ficha del libro (autor, fecha, idioma original, resumen).<br>
    • <strong>↺</strong> reinicia la navegación. <strong>⛶</strong> pantalla completa (como F11).</div></div>
    <div class="im-block"><div class="im-label">Búsquedas</div>
    <div class="im-text">• <strong>Buscador de versículos</strong>: escribe por ejemplo <code>Juan 3:16</code>, un rango o varios versículos. <strong>Tab</strong> completa el nombre del libro. Enter abre la referencia.<br>
    • 🎲 <strong>Dado</strong>: versículo al azar.<br>
    • Al escribir una palabra en cualquier momento puede abrirse la búsqueda central de palabras.</div></div>
    <div class="im-block"><div class="im-label">Lectura y versículos</div>
    <div class="im-text">• El encabezado del capítulo (libro, capítulo e instrucciones) permanece fijo al hacer scroll.<br>
    • Un clic en un versículo: favorito, nota y casilla de selección.<br>
    • <strong>Doble clic</strong> en una palabra: significado (si existe; si no hay definición, no aparece ventana).<br>
    • Marca casillas para elegir varios versículos y proyectarlos. «Quitar marcas» limpia la selección.</div></div>
    <div class="im-block"><div class="im-label">Barra de herramientas</div>
    <div class="im-text">• <strong>A− / A+</strong>: tamaño del texto.<br>
    • 🔍 <strong>Detalle</strong>: resalta nombres, ciudades y palabras de Jesús.<br>
    • 📚 Significados guardados · 📝 Notas · ♥ Favoritos.<br>
    • 📅 <strong>Plan 1 año</strong> (canónico, inverso, paralelo, cronológico; desde el 1 de enero o desde hoy).<br>
    • 📖 <strong>Glosario</strong> de términos bíblicos (lista completa, con buscador).<br>
    • 👤 <strong>Biografía</strong>: lista de personas, época (AT/NT), botón Atrás.<br>
    • 📜 <strong>Apócrifos</strong>: información y curiosidades (sin el texto de esos libros).<br>
    • ☁️ Nube / perfil Google · 🎬 Proyectar · ❓ Ayuda.</div></div>
    <div class="im-block"><div class="im-label">YouTube</div>
    <div class="im-text">Pega el enlace de un sermón. Al cargar un enlace, el vídeo aparece <strong>en la barra izquierda, debajo de la lista de libros</strong> (solo el vídeo). El ancho del vídeo sigue el de la barra; la lista de libros sigue arriba. Al borrar o cerrar el enlace, los libros vuelven a ocupar todo el lateral.</div></div>
    <div class="im-block"><div class="im-label">Proyección</div>
    <div class="im-text">Proyecta el versículo actual, el capítulo o la selección marcada. Desplazamiento automático con conteo y velocidades. <strong>Esc</strong> cierra la proyección.</div></div>
    <div class="im-block"><div class="im-label">Temas y pantalla</div>
    <div class="im-text">Diez temas (México, Corea, Ucrania, Day, Night, Reino, Edén, Arena, Sándalo, AMOLED). El botón +/− cambia el lote de cinco temas. La app ajusta márgenes según el ancho de la ventana.</div></div>
    <div class="im-block"><div class="im-label">Sincronización</div>
    <div class="im-text">Con Google puedes guardar notas, favoritos, significados y progreso en la nube. El perfil muestra logros e insignias por lectura.</div></div>
  `;
  document.getElementById('info-modal').classList.add('open');
  focusInfoScroll();
  document.getElementById('start-sefer-tour-btn')?.addEventListener('click', ()=>{
    startSeferTour();
  });
}
